import * as THREE from 'three/webgpu';
import { color, uniform, mix, uv, vec3 } from 'three/tsl';
import gsap from 'gsap';
import { createText } from '@/text';

export default function createNode(config, ctx) {
  const group = new THREE.Object3D();
  group.name = 'premium-pricing-card';

  const pos = config.scenePosition?.position ?? [0, 0, 0];
  const rot = config.scenePosition?.rotation ?? [0, 0, 0];
  const scl = config.scenePosition?.scale ?? [1, 1, 1];
  group.position.set(...pos);
  group.rotation.set(...rot);
  group.scale.set(...scl);

  const disposables = [];
  const timelines = [];

  const CARD_W = 2.4;
  const CARD_H = 3.2;
  const PAD = 0.5;
  const BASE = 0.25;

  // --- Background surface plane ---
  const bgGeo = new THREE.PlaneGeometry(CARD_W, CARD_H);
  const bgMat = new THREE.MeshStandardNodeMaterial({
    color: new THREE.Color('#16161d'),
    roughness: 0.6,
    metalness: 0.3,
  });
  const bgMesh = new THREE.Mesh(bgGeo, bgMat);
  bgMesh.position.z = 0;
  group.add(bgMesh);
  disposables.push(bgGeo, bgMat);

  // --- Hairline border ---
  const borderGeo = new THREE.PlaneGeometry(CARD_W + 0.012, CARD_H + 0.012);
  const borderMat = new THREE.MeshBasicNodeMaterial({ color: new THREE.Color('#2a2a33') });
  const borderMesh = new THREE.Mesh(borderGeo, borderMat);
  borderMesh.position.z = -0.001;
  group.add(borderMesh);
  disposables.push(borderGeo, borderMat);

  // --- Machined header strip ---
  const headerH = 0.08;
  const headerGeo = new THREE.PlaneGeometry(CARD_W, headerH);
  const headerMat = new THREE.MeshStandardNodeMaterial({
    color: new THREE.Color('#16161d'),
    roughness: 0.55,
    metalness: 0.5,
    clearcoat: 0.2,
  });
  // brushed anisotropic specular sweep via TSL uv-driven highlight
  const sweepPos = uniform(-0.3);
  const stripUv = uv();
  const band = stripUv.x.sub(sweepPos).abs().oneMinus().clamp(0.0, 1.0).pow(8.0);
  headerMat.emissiveNode = mix(vec3(0.0), color('#e8ecf2'), band).mul(0.6);
  const headerMesh = new THREE.Mesh(headerGeo, headerMat);
  headerMesh.position.set(0, CARD_H / 2 - headerH / 2, 0.001);
  group.add(headerMesh);
  disposables.push(headerGeo, headerMat);

  // --- Text content layout ---
  const textContent = config.textContent ?? [];
  const findText = (role) => textContent.find((t) => t.role === role)?.value;

  const topY = CARD_H / 2 - headerH - PAD;
  const textNodes = [];

  function addText(str, sizeEm, y, opts = {}) {
    if (!str) return null;
    const node = createText(str, {
      font: opts.font ?? 'JetBrains Mono',
      fontWeight: opts.fontWeight ?? 400,
      fontSize: sizeEm,
      letterSpacing: opts.letterSpacing ?? 0,
      color: opts.color ?? '#e8ecf2',
      align: opts.align ?? 'left',
      atlas: ctx.fontAtlas,
    });
    node.position.set(opts.x ?? -CARD_W / 2 + PAD, y, 0.002);
    group.add(node);
    textNodes.push(node);
    return node;
  }

  let cursorY = topY;

  addText(findText('tier-name') ?? 'ATELIER RESERVE', 0.2 * (20 / 20), cursorY, {
    fontWeight: 700,
    letterSpacing: 0.08,
    color: '#e8ecf2',
  });
  cursorY -= 0.34;

  addText(findText('price') ?? '$480', 0.62, cursorY, {
    font: 'Lora',
    fontWeight: 600,
    letterSpacing: -0.01,
    color: '#e8ecf2',
    x: -CARD_W / 2 + PAD,
  });

  addText(findText('caption') ?? 'PER MONTH, BILLED ANNUALLY', 0.09, cursorY - 0.16, {
    fontWeight: 400,
    letterSpacing: 0.12,
    color: '#8a8a94',
  });

  cursorY -= 0.62 + 0.5;

  const featureRoleValues = textContent
    .filter((t) => t.role === 'feature')
    .map((t) => t.value);
  const features = featureRoleValues.length
    ? featureRoleValues
    : [
        'Quarterly movement service',
        'Priority commission slots',
        'Private fitting lounge access',
        'Lifetime case refinishing',
      ];

  const rowH = BASE * 1.5;
  const featureNodes = [];
  features.forEach((feat, i) => {
    const y = cursorY - i * rowH;
    const t = addText(feat, 0.13, y, { fontWeight: 400, color: '#e8ecf2' });
    if (t) featureNodes.push(t);

    if (i < features.length - 1) {
      const hlGeo = new THREE.PlaneGeometry(CARD_W - PAD * 2, 0.006);
      const hlMat = new THREE.MeshBasicNodeMaterial({ color: new THREE.Color('#23232b') });
      const hlMesh = new THREE.Mesh(hlGeo, hlMat);
      hlMesh.position.set(0, y - rowH / 2, 0.0015);
      group.add(hlMesh);
      disposables.push(hlGeo, hlMat);
    }
  });

  // --- CTA row ---
  const ctaW = 1.4;
  const ctaH = 0.36;
  const ctaY = -CARD_H / 2 + 0.5 + ctaH / 2;
  const ctaGeo = new THREE.PlaneGeometry(ctaW, ctaH);
  const ctaMat = new THREE.MeshStandardNodeMaterial({ roughness: 0.5, metalness: 0.2 });
  const ctaUv = uv();
  const stopA = color('#ff4450');
  const stopB = color('#c1121f');
  ctaMat.colorNode = mix(stopA, stopB, ctaUv.y.oneMinus());
  ctaMat.emissiveNode = color('#ff2a38');
  ctaMat.emissiveIntensity = 1.5;
  const ctaMesh = new THREE.Mesh(ctaGeo, ctaMat);
  ctaMesh.position.set(0, ctaY, 0.003);
  ctaMesh.name = 'cta-row';
  group.add(ctaMesh);
  disposables.push(ctaGeo, ctaMat);

  addText(findText('cta-label') ?? 'JOIN THE RESERVE', 0.13, ctaY, {
    fontWeight: 700,
    letterSpacing: 0.08,
    color: '#16161d',
    align: 'center',
    x: 0,
  });

  // --- Cinematic primitives ---
  const primitives = config.cinematicPrimitives ?? [];
  primitives.forEach((p) => {
    const fn = ctx.primitives[p.name];
    if (fn) fn(group, p.params);
  });

  // --- Animation: weighted-settle mount ---
  group.scale.set(scl[0] * 1.04, scl[1] * 1.04, scl[2] * 1.04);
  const settleTl = gsap.timeline();
  settleTl.to(group.scale, {
    x: scl[0],
    y: scl[1],
    z: scl[2],
    duration: 0.9,
    ease: 'power4.out',
  });
  timelines.push(settleTl);

  // sweep specular band across header
  const sweepTl = gsap.timeline();
  sweepTl.to(sweepPos, { value: 1.3, duration: 0.9, ease: 'power2.out' });
  timelines.push(sweepTl);

  // feature stagger fade-up
  featureNodes.forEach((node, i) => {
    node.position.y -= 0.2;
    node.visible = true;
    if (node.material) node.material.opacity = 0;
    const tl = gsap.timeline({ delay: i * 0.08 });
    tl.to(node.position, {
      y: node.position.y + 0.2,
      duration: 0.5,
      ease: 'power2.out',
    });
    if (node.material) {
      tl.to(node.material, { opacity: 1, duration: 0.5, ease: 'power2.out' }, '<');
    }
    timelines.push(tl);
  });

  // --- CTA press-down interaction ---
  const handlers = {};
  handlers.onPointerDown = () => {
    const tl = gsap.timeline();
    tl.to(ctaMesh.scale, { x: 0.97, y: 0.97, duration: 0.12, ease: 'back.out' });
    timelines.push(tl);
  };
  handlers.onPointerUp = () => {
    const tl = gsap.timeline();
    tl.to(ctaMesh.scale, { x: 1, y: 1, duration: 0.12, ease: 'back.out' });
    timelines.push(tl);
  };

  group.userData.handlers = handlers;

  group.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    disposables.forEach((d) => {
      if (d && typeof d.dispose === 'function') d.dispose();
    });
    textNodes.forEach((node) => {
      if (node.geometry) node.geometry.dispose();
      if (node.material) node.material.dispose();
    });
  };

  return group;
}
